interface SortableItemProps {
  id: string;
  index: number;
  title: string;
  isActive: boolean;
  isChapter?: boolean;
  isExpanded?: boolean;
  hasContent?: boolean;
  onActivate: () => void;
  onToggleExpand?: () => void;
  onUpdateTitle?: (newTitle: string) => void;
  onDelete?: () => void;
  children?: React.ReactNode;
}

const SortableItem = ({ 
  id, 
  index, 
  title, 
  isActive, 
  isChapter, 
  isExpanded, 
  hasContent,
  onActivate, 
  onToggleExpand,
  onUpdateTitle,
  onDelete,
  children 
}: SortableItemProps) => {
  const [isEditing, setIsEditing] = React.useState(false);
  const [editValue, setEditValue] = React.useState(title);
  const [isDeleting, setIsDeleting] = React.useState(false);
  const longPressTimer = React.useRef<NodeJS.Timeout | null>(null);

  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id, disabled: isEditing || isDeleting });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    zIndex: isDragging ? 50 : 'auto',
  };

  const handleStartEdit = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsEditing(true);
    setEditValue(title);
  };

  const handleFinishEdit = () => {
    if (editValue.trim() && editValue !== title) {
        onUpdateTitle?.(editValue.trim());
    }
    setIsEditing(false);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleFinishEdit();
    if (e.key === 'Escape') {
        setIsEditing(false);
        setEditValue(title);
    }
  };

  const handleMouseDown = () => {
    longPressTimer.current = setTimeout(() => {
        setIsDeleting(true);
    }, 600);
  };

  const handleMouseUp = () => {
    if (longPressTimer.current) {
        clearTimeout(longPressTimer.current);
    }
  };

  return (
    <div ref={setNodeRef} style={style} className={cn("group/item", isChapter ? "mb-2" : "mb-1 ml-4")}>
      <div 
        className={cn(
            "flex items-center gap-2 p-1.5 rounded-lg transition-all duration-300 cursor-pointer border",
            isActive && !isDeleting
                ? "bg-primary/10 border-primary/20 shadow-sm" 
                : "bg-transparent border-transparent hover:bg-muted/10",
            isDeleting && "bg-red-500/10 border-red-500/30 text-red-600 shadow-[0_0_15px_rgba(239,68,68,0.1)]"
        )}
        onMouseDown={handleMouseDown}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onDoubleClick={handleStartEdit}
      >
        {/* Drag Handle or Delete Mode Icon */}
        <div 
          {...attributes} 
          {...listeners} 
          className={cn(
            "p-0.5 transition-all duration-300",
            isDeleting ? "opacity-100" : "opacity-0 group-hover/item:opacity-40 cursor-grab active:cursor-grabbing hover:opacity-100"
          )}
        >
          {isDeleting ? <Trash2 className="h-3 w-3 animate-bounce" onClick={(e) => { e.stopPropagation(); onDelete?.(); }} /> : <GripVertical className="h-3 w-3" />}
        </div>

        {/* Index & Title */}
        <div 
          className="flex-1 flex items-center gap-2 min-w-0"
          onClick={(e) => {
            e.stopPropagation();
            if (isDeleting) {
                setIsDeleting(false);
                return;
            }
            onActivate();
          }}
        >
          {isChapter && !isEditing && (
            <button 
              onClick={(e) => {
                e.stopPropagation();
                onToggleExpand?.();
              }}
              className="p-0.5 hover:bg-primary/10 rounded transition-colors"
            >
              {isExpanded ? <ChevronDown className="h-3 w-3" /> : <ChevronRight className="h-3 w-3" />}
            </button>
          )}

          {!isEditing && !isDeleting && (
            <div className={cn(
                "h-1.5 w-1.5 rounded-full shrink-0",
                hasContent ? "bg-green-500" : "bg-amber-500/60"
            )} />
          )}

