onPasteItem={(targetId, isChapter) => {
    if (!outlineClipboard) return;

    updateProject(p => {
        if (outlineClipboard.type === 'chapter') {
            const newChapterProps = { ...outlineClipboard.data, id: require('uuid').v4() };
            if (newChapterProps.sections) {
                newChapterProps.sections = newChapterProps.sections.map((s: any) => ({ ...s, id: require('uuid').v4() }));
            }
            const chapter = new Chapter(newChapterProps);
            const index = p.content.findIndex(c => c.id === targetId);
            const newContent = [...p.content];
            newContent.splice(index + 1, 0, chapter);
            return p.with({ content: newContent });
        } else {
            const info = p.findSection(targetId);
            if (info) {
                const newSectionProps = { ...outlineClipboard.data, id: require('uuid').v4() };
                const section = new Section(newSectionProps);
                return p.updateChapter(info.chapter.id, c => c.addSection(section, info.sectionIndex + 1));
            }
        }
    });
    toast({ title: 'Pasted', description: 'Item pasted from outline clipboard.' });
}}

